import math

def _render(cx, cy, a, b, th, amp):
    ct, st = math.cos(th), math.sin(th)
    out = []
    for i in range(16):
        for j in range(16):
            dx, dy = j - cx, i - cy
            u = dx * ct + dy * st
            v = -dx * st + dy * ct
            rho = math.sqrt((u / a) ** 2 + (v / b) ** 2)
            scale = 1.0 / math.sqrt((u / rho / a) ** 2 + (v / rho / b) ** 2) if rho else min(a, b)
            p = 0.5 + (1.0 - rho) * scale
            out.append(amp * max(0.0, min(1.0, p)))
    return out

