def _render(p):
    cx, cy, a, b, th, amp = p
    ct, st = math.cos(th), math.sin(th)
    out = []
    for i in range(16):
        for j in range(16):
            dx, dy = j - cx, i - cy
            u = dx * ct + dy * st
            v = -dx * st + dy * ct
            rho = math.sqrt((u / a) ** 2 + (v / b) ** 2)
            if rho == 0.0:
                dist = min(a, b)
            else:
                # Approximate signed distance to the ellipse boundary.
                dist = (1.0 - rho) / math.sqrt(
                    (u / (a * a)) ** 2 + (v / (b * b)) ** 2
                )
            out.append(amp * max(0.0, min(1.0, dist + 0.5)))
    return out


