import math

def _render(cx, cy, a, b, th, amp):
    ct, st = math.cos(th), math.sin(th)
    out = []
    for i in range(16):
        for j in range(16):
            dx, dy = j - cx, i - cy
            u = dx * ct + dy * st
            v = -dx * st + dy * ct
            rho = math.sqrt((u / a) ** 2 + (v / b) ** 2)
            grad = math.sqrt((u / (a * a)) ** 2 + (v / (b * b)) ** 2)
            d = (1.0 - rho) / max(grad, 1e-10)
            out.append(amp * max(0.0, min(1.0, d + 0.5)))
    return out

def encode(img):
    def moments(t):
        sw = sx = sy = 0.0
        for i in range(16):
            for j in range(16):
                w = max(0.0, img[16*i+j] - t)
                sw += w
                sx += w*j
                sy += w*i
        if sw < 1e-9:
            return [7.5, 7.5, 2.5, 2.0, 0.0]
        cx, cy = sx/sw, sy/sw
        xx = yy = xy = 0.0
        for i in range(16):
            for j in range(16):
                w = max(0.0, img[16*i+j] - t)
                dx, dy = j-cx, i-cy
                xx += w*dx*dx
                yy += w*dy*dy
                xy += w*dx*dy
        xx, yy, xy = xx/sw, yy/sw, xy/sw
        disc = math.sqrt(max(0.0, (xx-yy)**2 + 4*xy*xy))
        a = max(1.0, min(5.5, 2*math.sqrt(max(0.2, (xx+yy+disc)/2))))
        b = max(1.0, min(5.5, 2*math.sqrt(max(0.2, (xx+yy-disc)/2))))
        return [cx, cy, a, b, 0.5*math.atan2(2*xy, xx-yy)]

    def evaluate(p):
        sh = _render(p[0], p[1], p[2], p[3], p[4], 1.0)
        dot = sum(x*y for x, y in zip(img, sh))
        norm = sum(y*y for y in sh)
        amp = max(0.35, min(1.2, dot/max(norm, 1e-12)))
        return sum((x-amp*y)**2 for x, y in zip(img, sh)), amp

    starts = []
    for t in (0.08, 0.16, 0.24, 0.32):
        p = moments(t)
        for da, db, dt in ((0,0,0), (0,0,math.pi/2),
                           (0,0,math.pi/4), (0,0,-math.pi/4)):
            starts.append([p[0], p[1], p[2]+da, p[3]+db, p[4]+dt])

    best_loss, best = float("inf"), None
    for p in starts:
        p = p[:]
        steps = [0.24, 0.24, 0.22, 0.22, 0.12]
        loss, amp = evaluate(p)
        while max(steps) > 0.0008:
            changed = False
            for k in range(5):
                for sign in (-1, 1):
                    q = p[:]
                    q[k] += sign * steps[k]
                    if k < 2:
                        q[k] = max(-0.5, min(15.5, q[k]))
