                        q[k] = max(0.9, min(5.8, q[k]))
                    val, qa = evaluate(q)
                    if val < loss:
                        p, loss, amp = q, val, qa
                        changed = True
            if not changed:
                steps = [s * 0.62 for s in steps]
        if loss < best_loss:
            best_loss, best = loss, p + [amp]
    return best

